# PLC Rack 3D (WebDev rack3d/*): READ ONLY rack / IO state for the three.js page, and the locally served static files.
# Generated by .cursor/tasks/plc-rack-3d/build.py (docs/plc-rack-3d.md) - edit the builder's src, not this copy.
# Nothing here writes a tag: system.tag.readBlocking only, and only below [default]Boars_Head/ (never [RCP1] or
# [default]_RCP1_). Callers check the login first (shared.WebAuth.perspectiveUser).
import re

LOGGER = "BH.Rack3d"
LIST_TAG = "[default]_Config/PLCs/List"
DEFAULT_FOLDER = "[default]Boars_Head/GrovePort/Machine Room/PLC/"
SITE_PREFIX = "[default]Boars_Head/"
_NAME = re.compile(r"^[A-Za-z0-9_\-]{1,40}$")
CTRL = ["Connected", "Mode", "Run", "MajorFault", "MinorFault", "IOFault", "KeySwitch", "ControllerName", "CatalogNumber",
        "ModulesFaulted", "ModuleCount", "MajorFaultRecordCode", "MajorRevision", "MinorRevision"]
# files served by rack3d/lib (whitelist; anything else is 404)
FILES = {"three.module.min.js": "text/javascript; charset=utf-8", "OrbitControls.js": "text/javascript; charset=utf-8",
         "RoomEnvironment.js": "text/javascript; charset=utf-8", "rack3d.js": "text/javascript; charset=utf-8",
         "rack3d.css": "text/css; charset=utf-8", "demo-state.json": "application/json; charset=utf-8",
         "view.html": "text/html; charset=utf-8", "LICENSE-three.txt": "text/plain; charset=utf-8"}
LIB_REL = "projects/BH/com.inductiveautomation.webdev/resources/rack3d/lib/"


def param(request, key, default=""):
	try:
		v = (request.get("params") or {}).get(key)
	except:
		v = None
	if v is None:
		return default
	if not isinstance(v, basestring):
		try:
			v = v[0] if len(v) else default
		except:
			pass
	return unicode(v)


def _py(v):
	"""Document tag value -> plain Python (dict / list)."""
	if v is None:
		return None
	try:
		if hasattr(v, "toDict"):
			v = v.toDict()
		return system.util.jsonDecode(system.util.jsonEncode(v))
	except:
		try:
			return system.util.jsonDecode(unicode(v))
		except:
			return None


def sitePath(plc):
	"""Site UDT instance of a PLC name: the _Config/PLCs/List entry, else the Groveport Machine Room folder."""
	if not _NAME.match(plc or ""):
		return None
	path = None
	try:
		lst = _py(system.tag.readBlocking([LIST_TAG])[0].value) or {}
		for e in lst.get("plcs") or []:
			if unicode(e.get("name")) == plc and e.get("path"):
				path = unicode(e.get("path"))
				break
	except:
		path = None
	path = path or (DEFAULT_FOLDER + plc)
	return path if path.startswith(SITE_PREFIX) else None


def screwType(plc):
	"""'phillips' (default) or 'flat': the screwType of this PLC's _Config/PLCs/List entry (Designer Tag Browser only)."""
	try:
		lst = _py(system.tag.readBlocking([LIST_TAG])[0].value) or {}
		for e in lst.get("plcs") or []:
			if unicode(e.get("name")) == plc:
				return "flat" if unicode(e.get("screwType") or "").strip().lower() == "flat" else "phillips"
	except:
		pass
	return "phillips"


def _good(qv):
	try:
		return qv.quality.isGood()
	except:
		return False


def _val(qv):
	return qv.value if _good(qv) else None


def _bits(v):
	if v is None:
		return None
	v = int(v) & 0xFFFF
	return [(v >> i) & 1 for i in range(16)]


def _num(v):
	try:
		return None if v is None else round(float(v), 4)
	except:
		return None


def state(request):
	plc = param(request, "plc", "RCP1")
	site = sitePath(plc)
	if site is None:
		return {"ok": False, "reason": "Unknown PLC", "plc": plc}
	head = system.tag.readBlocking([site + "/" + m for m in CTRL] + [site + "/Rack"])
	c = dict(zip(CTRL, head[:-1]))
	rack = _py(head[-1].value) if _good(head[-1]) else None
	if not rack or not rack.get("slots"):
		return {"ok": False, "reason": "No Rack Data", "plc": plc}
	conn = _good(c["Connected"]) and bool(c["Connected"].value)
	slots = rack.get("slots") or []
	paths, plan = [], []
	for s in slots:
		base = site + "/" + unicode(s.get("member"))
		kind = s.get("type")
		names = ["Faulted", "Fault"]
		if kind == "DI":
			names += ["Data"]
		elif kind == "DO":
			names += ["Data", "ReadBack"]
		elif kind == "AI":
			for n in range(8):
				names += ["Ch%dSignal" % n, "Ch%dUnit" % n, "Ch%dOverRange" % n, "Ch%dUnderRange" % n]
		plan.append((s, len(paths), names))
		paths += [base + "/" + n for n in names]
	vals = system.tag.readBlocking(paths) if paths else []
	out = []
	for s, i0, names in plan:
		q = dict(zip(names, vals[i0:i0 + len(names)]))
		faulted = _val(q["Faulted"])
		e = {"slot": s.get("slot"), "member": s.get("member"), "name": s.get("name"), "catalog": s.get("catalog"),
		     "type": s.get("type"), "points": s.get("points"), "description": s.get("description"),
		     "ok": None if (faulted is None or not conn) else (not bool(faulted)),
		     "fault": _val(q["Fault"]) if conn else None}
		if s.get("type") in ("DI", "DO"):
			e["data"] = _bits(_val(q["Data"])) if conn else None
		if s.get("type") == "DO":
			e["readBack"] = _bits(_val(q["ReadBack"])) if conn else None
		if s.get("type") == "AI":
			e["channels"] = [{"v": _num(_val(q["Ch%dSignal" % n])) if conn else None,
			                  "unit": _val(q["Ch%dUnit" % n]),
			                  "over": bool(_val(q["Ch%dOverRange" % n])) if conn else None,
			                  "under": bool(_val(q["Ch%dUnderRange" % n])) if conn else None} for n in range(8)]
		out.append(e)
	ctl = rack.get("controller") or {}
	g = lambda k: _val(c[k]) if conn else None
	maj, mnr = _val(c["MajorRevision"]), _val(c["MinorRevision"])
	res = {"ok": True, "plc": plc, "comm": conn, "screwType": screwType(plc), "ts": system.date.toMillis(system.date.now()),
	       "controller": {"name": _val(c["ControllerName"]) or ctl.get("name"),
	                      "catalog": _val(c["CatalogNumber"]) or ctl.get("catalog"),
	                      "family": ctl.get("family"), "mode": g("Mode"), "run": g("Run"), "majorFault": g("MajorFault"),
	                      "minorFault": g("MinorFault"), "ioFault": g("IOFault"), "keySwitch": g("KeySwitch"),
	                      "modulesFaulted": _val(c["ModulesFaulted"]), "moduleCount": _val(c["ModuleCount"]),
	                      "faultCode": _val(c["MajorFaultRecordCode"]),
	                      "firmware": ("%s.%s" % (maj, mnr)) if maj is not None and mnr is not None else None},
	       "slots": out}
	if param(request, "labels") == "1":
		res["labels"] = dict((unicode(s.get("slot")), s.get("pointNames") or {}) for s in slots)
		res["channelsCfg"] = dict((unicode(s.get("slot")), s.get("channels") or {}) for s in slots
		                          if s.get("type") == "AI")
	return res


def _libDir(request):
	try:
		d = request["context"].getSystemManager().getDataDir().getAbsolutePath()
	except:
		d = "/usr/local/bin/ignition/data"
	return d.rstrip("/") + "/" + LIB_REL


def serveFile(request, name):
	"""Bytes of one whitelisted rack3d/lib file (read from the project folder on the gateway; cached per mtime)."""
	from java.io import File
	from java.nio.file import Files
	ctype = FILES.get(name)
	if ctype is None:
		return None
	f = File(_libDir(request) + name)
	if not f.isFile():
		return None
	key = "bh.rack3d.file." + name
	store = system.util.getGlobals()
	hit = store.get(key)
	if hit is None or hit[0] != f.lastModified():
		hit = (f.lastModified(), Files.readAllBytes(f.toPath()))
		store[key] = hit
	return {"bytes": hit[1], "contentType": ctype}
